import json, os
raw = os.environ.get('DSH_INPUT', '')
try:
    ev = json.loads(raw) if raw.strip() else {}
except Exception:
    ev = {'raw': raw}
scope = {'source': ev.get('source'), 'kind': ev.get('kind')}
reasons = []
if scope['source'] != 'aone' or scope['kind'] != 'bug':
    reasons.append('source out of scope')
if ev.get('status') != 'afk':
    reasons.append('ticket not afk')
out = {'scope': scope, 'gate': {'pass': len(reasons) == 0, 'reasons': reasons}, 'event': ev}
print(json.dumps(out, ensure_ascii=False))

import json, os
raw = os.environ.get('DSH_INPUT', '')
text = raw.strip()
if text.startswith('```'):
    lines = text.splitlines()[1:]
    if lines and lines[-1].strip().startswith('```'):
        lines = lines[:-1]
    text = '\n'.join(lines)
try:
    a = json.loads(text)
except Exception:
    a = {'route': None, 'parse_error': True, 'echo': {'gate': {'pass': False, 'reasons': ['unparseable-assessment']}}}
echo = a.get('echo') or {}
gate = echo.get('gate') or {}
route = a.get('route')
ok = gate.get('pass') is True and route in ('worker', 'hitl', 'ignore')
out = {
    'id': (echo.get('event') or {}).get('id'),
    'assignment': ('coding-worker' if route == 'worker' else route) if ok else 'drop',
    'priority': a.get('priority'),
    'basis': a.get('reason'),
    'gatePass': gate.get('pass') is True,
    'gateReasons': gate.get('reasons') or ([] if gate.get('pass') is True else ['missing-gate-echo']),
}
print(json.dumps(out, ensure_ascii=False))
